    21→// commitInfo holds information about a commit for display purposes.
    22→type commitInfo struct {
    23→	SHA       string
    24→	ShortSHA  string
    25→	Message   string
    26→	Author    string
    27→	Email     string
    28→	Date      time.Time
    29→	Files     []string
    30→	HasEntire bool
    31→	SessionID string
    32→}
    33→
    34→// interaction holds a single prompt and its responses for display.
    35→type interaction struct {
    36→	Prompt    string
    37→	Responses []string // Multiple responses can occur between tool calls
    38→	Files     []string
    39→}
    40→
    41→// checkpointDetail holds detailed information about a checkpoint for display.
    42→type checkpointDetail struct {
    43→	Index            int
    44→	ShortID          string
    45→	Timestamp        time.Time
    46→	IsTaskCheckpoint bool
    47→	Message          string
    48→	// Interactions contains all prompt/response pairs in this checkpoint.
    49→	// Most strategies have one, but shadow condensations may have multiple.
    50→	Interactions []interaction
    51→	// Files is the aggregate list of all files modified (for backwards compat)
    52→	Files []string
    53→}
