    55→func newExplainCmd() *cobra.Command {
    56→	var sessionFlag string
    57→	var commitFlag string
    58→	var noPagerFlag bool
    59→
    60→	cmd := &cobra.Command{
    61→		Use:   "explain",
    62→		Short: "Explain a session or commit",
    63→		Long: `Explain provides human-readable context about sessions and commits.
    64→
    65→Use this command to understand what happened during agent-driven development,
    66→either for self-review or to understand a teammate's work.
    67→
    68→By default, explains the current session. Use flags to explain a specific
    69→session or commit.`,
    70→		RunE: func(cmd *cobra.Command, _ []string) error {
    71→			// Check if Entire is disabled
    72→			if checkDisabledGuard(cmd.OutOrStdout()) {
    73→				return nil
    74→			}
    75→
    76→			return runExplain(cmd.OutOrStdout(), sessionFlag, commitFlag, noPagerFlag)
    77→		},
    78→	}
    79→
    80→	cmd.Flags().StringVar(&sessionFlag, "session", "", "Explain a specific session (ID or prefix)")
    81→	cmd.Flags().StringVar(&commitFlag, "commit", "", "Explain a specific commit (SHA or ref)")
    82→	cmd.Flags().BoolVar(&noPagerFlag, "no-pager", false, "Disable pager output")
    83→
    84→	return cmd
    85→}
    86→
    87→// runExplain routes to the appropriate explain function based on flags.
    88→func runExplain(w io.Writer, sessionID, commitRef string, noPager bool) error {
    89→	// Error if both flags are provided
    90→	if sessionID != "" && commitRef != "" {
    91→		return errors.New("cannot specify both --session and --commit")
    92→	}
    93→
    94→	// Route to appropriate handler
    95→	if sessionID != "" {
    96→		return runExplainSession(w, sessionID, noPager)
    97→	}
    98→	if commitRef != "" {
    99→		return runExplainCommit(w, commitRef)
   100→	}
   101→
   102→	// Default: explain current session
   103→	return runExplainDefault(w, noPager)
   104→}
   105→
   106→// runExplainDefault explains the current session.
   107→func runExplainDefault(w io.Writer, noPager bool) error {
   108→	// Read current session
   109→	currentSessionID, err := paths.ReadCurrentSession()
   110→	if err != nil {
   111→		return fmt.Errorf("failed to read current session: %w", err)
   112→	}
   113→
   114→	if currentSessionID == "" {
   115→		return errors.New("no active session. Use --session or --commit to specify what to explain")
   116→	}
   117→
   118→	return runExplainSession(w, currentSessionID, noPager)
   119→}
   120→
   121→// runExplainSession explains a specific session.
   122→func runExplainSession(w io.Writer, sessionID string, noPager bool) error {
   123→	strat := GetStrategy()
   124→
   125→	// Get session details
   126→	session, err := strategy.GetSession(sessionID)
   127→	if err != nil {
   128→		if errors.Is(err, strategy.ErrNoSession) {
   129→			return fmt.Errorf("session not found: %s", sessionID)
   130→		}
   131→		return fmt.Errorf("failed to get session: %w", err)
   132→	}
   133→
   134→	// Get source ref (metadata branch + commit) for this session
   135→	sourceRef := strat.GetSessionMetadataRef(session.ID)
   136→
   137→	// Gather checkpoint details
   138→	checkpointDetails := gatherCheckpointDetails(strat, session)
   139→
   140→	// For strategies like shadow where active sessions may not have checkpoints,
   141→	// try to get the current session transcript directly
   142→	if len(checkpointDetails) == 0 && len(session.Checkpoints) == 0 {
   143→		checkpointDetails = gatherCurrentSessionDetails(strat, session)
   144→	}
   145→
   146→	// Format output
   147→	output := formatSessionInfo(session, sourceRef, checkpointDetails)
   148→
   149→	// Output with pager if appropriate
   150→	if noPager {
   151→		fmt.Fprint(w, output)
   152→	} else {
   153→		outputWithPager(w, output)
   154→	}
   155→
   156→	return nil
   157→}
