    36→func TestExplainSession_NotFound(t *testing.T) {
    37→	tmpDir := t.TempDir()
    38→	t.Chdir(tmpDir)
    39→
    40→	// Initialize git repo
    41→	if _, err := git.PlainInit(tmpDir, false); err != nil {
    42→		t.Fatalf("failed to init git repo: %v", err)
    43→	}
    44→
    45→	// Create .entire directory
    46→	if err := os.MkdirAll(".entire", 0o750); err != nil {
    47→		t.Fatalf("failed to create .entire dir: %v", err)
    48→	}
    49→
    50→	var stdout bytes.Buffer
    51→	err := runExplainSession(&stdout, "nonexistent-session", false)
    52→
    53→	if err == nil {
    54→		t.Error("expected error for nonexistent session, got nil")
    55→	}
    56→	if !strings.Contains(err.Error(), "not found") {
    57→		t.Errorf("expected 'not found' in error, got: %v", err)
    58→	}
    59→}
