    81→func TestExplainCommit_NoEntireData(t *testing.T) {
    82→	tmpDir := t.TempDir()
    83→	t.Chdir(tmpDir)
    84→
    85→	// Initialize git repo
    86→	repo, err := git.PlainInit(tmpDir, false)
    87→	if err != nil {
    88→		t.Fatalf("failed to init git repo: %v", err)
    89→	}
    90→
    91→	w, err := repo.Worktree()
    92→	if err != nil {
    93→		t.Fatalf("failed to get worktree: %v", err)
    94→	}
