### 4. Test Utilities Architecture

#### 4.1 Git Repository Management (`git-repo.ts`)

```typescript
import { execSync, exec } from 'child_process';
import * as fs from 'fs';
import * as path from 'path';
import * as os from 'os';

export class TestRepo {
  readonly path: string;

  constructor() {
    // Create isolated temp directory (similar to Go's t.TempDir())
    this.path = fs.mkdtempSync(path.join(os.tmpdir(), 'entire-e2e-'));
  }

  async init(): Promise<void> {
    await this.git('init');
    await this.git('config', 'user.email', 'test@example.com');
    await this.git('config', 'user.name', 'Test User');
  }

  async writeFile(relativePath: string, content: string): Promise<void> {
    const fullPath = path.join(this.path, relativePath);
    await fs.promises.mkdir(path.dirname(fullPath), { recursive: true });
    await fs.promises.writeFile(fullPath, content);
  }

  async readFile(relativePath: string): Promise<string> {
    return fs.promises.readFile(path.join(this.path, relativePath), 'utf-8');
  }

  async fileExists(relativePath: string): Promise<boolean> {
    try {
      await fs.promises.access(path.join(this.path, relativePath));
      return true;
    } catch {
      return false;
    }
  }

  async git(...args: string[]): Promise<string> {
    return new Promise((resolve, reject) => {
      exec(`git ${args.join(' ')}`, { cwd: this.path }, (err, stdout, stderr) => {
        if (err) reject(new Error(`git ${args[0]} failed: ${stderr}`));
        else resolve(stdout.trim());
      });
    });
  }

  async getHeadHash(): Promise<string> {
    return this.git('rev-parse', 'HEAD');
  }

  async branchExists(branchName: string): Promise<boolean> {
    try {
      await this.git('rev-parse', '--verify', `refs/heads/${branchName}`);
      return true;
    } catch {
      return false;
    }
  }

  async cleanup(): Promise<void> {
    await fs.promises.rm(this.path, { recursive: true, force: true });
  }
}
```

#### 4.2 CLI Runner (`cli-runner.ts`)

```typescript
import { exec } from 'child_process';
import * as path from 'path';

export class CLIRunner {
  constructor(
    private binPath: string,
    private repoPath: string,
    private claudeProjectDir: string
  ) {}

  async run(...args: string[]): Promise<{ stdout: string; stderr: string }> {
    return new Promise((resolve, reject) => {
      exec(
        `${this.binPath} ${args.join(' ')}`,
        {
          cwd: this.repoPath,
          env: {
            ...process.env,
            ENTIRE_TEST_CLAUDE_PROJECT_DIR: this.claudeProjectDir,
          },
        },
        (err, stdout, stderr) => {
          if (err) reject(new Error(`CLI failed: ${stderr}\n${stdout}`));
          else resolve({ stdout, stderr });
        }
      );
    });
  }

  async enable(strategy: string): Promise<void> {
    await this.run('enable', '--agent', 'claude-code', '--strategy', strategy);
  }

  async rewindList(): Promise<RewindPoint[]> {
    const { stdout } = await this.run('rewind', '--list');
    return JSON.parse(stdout);
  }

  async rewind(checkpointId: string): Promise<void> {
    await this.run('rewind', '--to', checkpointId);
  }
}

interface RewindPoint {
  id: string;
  message: string;
  metadata_dir: string;
  date: string;
  is_task_checkpoint: boolean;
  is_logs_only: boolean;
}
```

#### 4.3 Git Assertions (`git-assertions.ts`)

```typescript
import { expect } from 'vitest';
