export async function assertMetadataBranchExists(repo: TestRepo): Promise<void> {
  const exists = await repo.branchExists('entire/sessions');
  expect(exists, 'Metadata branch entire/sessions should exist').toBe(true);
}

export async function assertCheckpointMetadata(
  repo: TestRepo,
  checkpointId: string
): Promise<void> {
  // Sharded path: <id[:2]>/<id[2:]>/metadata.json
  const shardedPath = `${checkpointId.slice(0, 2)}/${checkpointId.slice(2)}`;
  const metadataPath = `${shardedPath}/metadata.json`;

  // Read from entire/sessions branch
  const content = await repo.git('show', `entire/sessions:${metadataPath}`);
  const metadata = JSON.parse(content);

  expect(metadata.checkpoint_id).toBe(checkpointId);
  expect(metadata.strategy).toBeDefined();
}
```

