        UserPromptSubmit: [{
          matcher: '',
          hooks: [{ type: 'command', command: `${this.cli['binPath']} hooks claude-code user-prompt-submit` }]
        }],
        Stop: [{
          matcher: '',
          hooks: [{ type: 'command', command: `${this.cli['binPath']} hooks claude-code stop` }]
        }],
        PreToolUse: [{
          matcher: 'Task',
          hooks: [{ type: 'command', command: `${this.cli['binPath']} hooks claude-code pre-task` }]
        }],
        PostToolUse: [
          {
            matcher: 'Task',
            hooks: [{ type: 'command', command: `${this.cli['binPath']} hooks claude-code post-task` }]
          },
          {
            matcher: 'TodoWrite',
            hooks: [{ type: 'command', command: `${this.cli['binPath']} hooks claude-code post-todo` }]
          }
        ]
      }
    };

    const claudeDir = path.join(this.repo.path, '.claude');
    await fs.promises.mkdir(claudeDir, { recursive: true });
    await fs.promises.writeFile(
      path.join(claudeDir, 'settings.json'),
      JSON.stringify(settings, null, 2)
    );
  }

  async runClaude(prompt: string): Promise<string> {
    let result = '';

    for await (const message of query({
      prompt,
      options: {
        cwd: this.repo.path,
        settingSources: ['project'], // Load hooks from .claude/settings.json
        allowedTools: ['Read', 'Write', 'Edit', 'Bash', 'Glob'],
        permissionMode: 'acceptEdits', // Auto-approve edits for e2e tests
      }
    })) {
      if ('result' in message) {
        result = message.result;
      }
    }

    return result;
  }

  async cleanup(): Promise<void> {
    await this.repo.cleanup();
    await fs.promises.rm(this.claudeProjectDir, { recursive: true, force: true });
  }
}
