### 5. Sample Test Implementation

#### `src/tests/manual-commit.test.ts`

```typescript
import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { E2ETestEnv } from '../utils/test-env';
import {
  assertShadowBranchExists,
  assertMetadataBranchExists,
  assertCheckpointMetadata,
} from '../utils/git-assertions';

describe('Manual-Commit Strategy E2E', () => {
  let env: E2ETestEnv;
  const binPath = process.env.ENTIRE_BIN_PATH!;

  beforeEach(async () => {
    env = new E2ETestEnv(binPath);
    await env.setup('manual-commit');
  });

  afterEach(async () => {
    await env.cleanup();
  });

  it('creates shadow branch and checkpoint after Claude session', async () => {
    const initialHead = await env.repo.getHeadHash();

    // Run Claude with a simple prompt
    await env.runClaude('Create a file called hello.txt with the content "Hello World"');

    // Verify file was created
    const fileExists = await env.repo.fileExists('hello.txt');
    expect(fileExists).toBe(true);

    const content = await env.repo.readFile('hello.txt');
    expect(content).toContain('Hello');

    // Verify shadow branch was created
    await assertShadowBranchExists(env.repo, initialHead);

    // Verify rewind points exist
    const rewindPoints = await env.cli.rewindList();
    expect(rewindPoints.length).toBeGreaterThan(0);
    expect(rewindPoints[0].message).toBeDefined();
  });

  it('condenses session to metadata branch on user commit', async () => {
    // Run Claude session
    await env.runClaude('Create main.go with a simple hello world program');

    // User commits (with hooks)
    await env.repo.git('add', 'main.go');
    await env.repo.git('commit', '-m', 'Add main.go');

    // Verify metadata branch exists
    await assertMetadataBranchExists(env.repo);

    // Get checkpoint ID from commit message
    const commitMsg = await env.repo.git('log', '-1', '--format=%B');
    const match = commitMsg.match(/Entire-Checkpoint: ([a-f0-9]+)/);
    expect(match).not.toBeNull();

    const checkpointId = match![1];
    await assertCheckpointMetadata(env.repo, checkpointId);
  });

  it('preserves untracked files during rewind', async () => {
    // Create untracked file before session
    await env.repo.writeFile('config.json', '{"setting": true}');

    // Run Claude session - creates checkpoint 1
    await env.runClaude('Create file a.txt with content "checkpoint 1"');

    const rewindPoints1 = await env.cli.rewindList();
    const checkpoint1 = rewindPoints1[0];

    // Continue session - creates checkpoint 2
    await env.runClaude('Create file b.txt with content "checkpoint 2"');

    // Rewind to checkpoint 1
    await env.cli.rewind(checkpoint1.id);

    // Verify a.txt exists (from checkpoint 1)
    expect(await env.repo.fileExists('a.txt')).toBe(true);

    // Verify b.txt was removed (created after checkpoint 1)
    expect(await env.repo.fileExists('b.txt')).toBe(false);

    // Verify config.json is preserved (existed before session)
    expect(await env.repo.fileExists('config.json')).toBe(true);
    const configContent = await env.repo.readFile('config.json');
    expect(configContent).toBe('{"setting": true}');
  });
});
