   405→// isEntireHook checks if a command is an Entire hook (old or new format)
   406→func isEntireHook(command string) bool {
   407→	for _, prefix := range entireHookPrefixes {
   408→		if strings.HasPrefix(command, prefix) {
   409→			return true
   410→		}
   411→	}
   412→	return false
   413→}
   414→
   415→// removeEntireHooks removes all Entire hooks from a list of matchers (for simple hooks like Stop)
   416→func removeEntireHooks(matchers []ClaudeHookMatcher) []ClaudeHookMatcher {
   417→	result := make([]ClaudeHookMatcher, 0, len(matchers))
   418→	for _, matcher := range matchers {
   419→		filteredHooks := make([]ClaudeHookEntry, 0, len(matcher.Hooks))
   420→		for _, hook := range matcher.Hooks {
   421→			if !isEntireHook(hook.Command) {
   422→				filteredHooks = append(filteredHooks, hook)
   423→			}
   424→		}
   425→		// Only keep the matcher if it has hooks remaining
   426→		if len(filteredHooks) > 0 {
   427→			matcher.Hooks = filteredHooks
   428→			result = append(result, matcher)
   429→		}
   430→	}
   431→	return result
   432→}
   433→
   434→// removeEntireHooksFromMatchers removes Entire hooks from tool-use matchers (PreToolUse, PostToolUse)
   435→// This handles the nested structure where hooks are grouped by tool matcher (e.g., "Task", "TodoWrite")
   436→func removeEntireHooksFromMatchers(matchers []ClaudeHookMatcher) []ClaudeHookMatcher {
   437→	// Same logic as removeEntireHooks - both work on the same structure
   438→	return removeEntireHooks(matchers)
   439→}
