   1→//! Layer sync protocol tests
   2→//!
   3→//! Tests that layer data flows between peers after publish:
   4→//! - Owner edits map layer → node receives data
   5→//! - Owner edits list layer (chat messages) → node receives data
   6→//! - Viewer connects → receives page metadata with encrypted key
   7→//! - Full chain: owner writes → node relay → viewer receives
   8→
   9→use std::time::Duration;
  10→
  11→use anyhow::Result;
  12→use tokio::time::sleep;
  13→use serde_json::Value;
  14→use tracing::info;
  15→use courier::trace::TraceDirection;
  16→
  17→use butler::ScribeMessage;
  18→use crate::fixtures::{init_tracing, wait_for_layer_data, wait_until};
  19→use crate::peer::Peer;
  20→use crate::scenario::Scenario;
  21→
  22→async fn get_layer_json(peer: &Peer, page_id: &str, layer_name: &str) -> Result<Value> {
  23→    let scribe = peer.butler.open_page(page_id).await?;
  24→    let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
  25→    scribe
  26→        .cast(ScribeMessage::GetLayerData {
  27→            layer_name: layer_name.to_string(),
  28→            reply: reply_tx,
  29→        })
  30→        .map_err(|e| anyhow::anyhow!("GetLayerData cast failed: {:?}", e))?;
  31→
  32→    reply_rx
  33→        .await
  34→        .map_err(|_| anyhow::anyhow!("GetLayerData channel closed"))?
  35→        .map_err(|e| anyhow::anyhow!("GetLayerData failed: {}", e))
  36→}
  37→
  38→fn expected_sync_layers_from_permit(permit: &gurkha::Permit, page_id: &str) -> Vec<String> {
  39→    let page_prefix = format!("{}/", page_id);
  40→    let mut layers = Vec::new();
  41→    for (name, config) in permit.layers() {
  42→        if !config.sync || name.starts_with("__sync_meta/") {
  43→            continue;
  44→        }
  45→        let normalized = name.strip_prefix(&page_prefix).unwrap_or(name).to_string();
  46→        layers.push(normalized);
  47→    }
  48→    layers.sort();
  49→    layers.dedup();
  50→    layers
  51→}
  52→
  53→fn assert_sync_meta_entries(sync_meta: &Value, expected_layers: &[String]) {
  54→    let meta_obj = sync_meta
  55→        .as_object()
  56→        .expect("sync-meta should be a map object");
  57→
  58→    for layer in expected_layers {
  59→        let entry = meta_obj
  60→            .get(layer)
  61→            .unwrap_or_else(|| panic!("sync-meta missing expected layer entry: {}", layer));
  62→        let synced = entry
  63→            .get("synced")
  64→            .and_then(Value::as_bool)
  65→            .unwrap_or(false);
  66→        let version = entry
  67→            .get("version")
  68→            .and_then(Value::as_u64)
  69→            .unwrap_or(0);
  70→        assert!(synced, "expected synced=true for layer {}", layer);
  71→        assert_eq!(version, 1, "expected version=1 for layer {}", layer);
  72→    }
  73→}
  74→
  75→/// Owner writes to map layer (reactions), node receives via SyncOffer
  76→///
  77→/// **Bug coverage**: "Permission denied: cannot write to layer" where
  78→/// node's Scribe rejects owner SyncOffers because Permissions::can_write()
  79→/// fails on all 3 paths (subscriber, sync_target, stored permit).
  80→///
  81→/// Uses "reactions" — the map layer defined in osvauld-demos's permit_template.json.
  82→#[tokio::test]
  83→async fn test_owner_layer_sync_to_node() -> Result<()> {
  84→    init_tracing();
  85→
  86→    let mut s = Scenario::builder()
  87→        .app("osvauld-demos")
  88→        .published()
  89→        .build()
  90→        .await?;
  91→
  92→    let page_id = s.space().page_id.clone();
  93→
  94→    // Give time for PageAnnounceAck + Scribe subscription
  95→    sleep(Duration::from_millis(500)).await;
  96→
  97→    // Owner opens page and writes to a map layer
  98→    let owner_scribe = s.owner().butler.open_page(&page_id).await?;
  99→
 100→    // Write data to "reactions" (a map layer in the osvauld-demos permit)
 101→    let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
 102→    owner_scribe.cast(ScribeMessage::EnsureLoroMap {
 103→        layer_name: "reactions".to_string(),
 104→        reply: reply_tx,
 105→    }).map_err(|e| anyhow::anyhow!("Failed to ensure map: {:?}", e))?;
 106→    reply_rx.await??;
 107→
 108→    owner_scribe.cast(ScribeMessage::MapInsert {
 109→        layer_name: "reactions".to_string(),
 110→        path: String::new(),
 111→        key: "msg1".to_string(),
 112→        value: serde_json::json!({"emoji": "thumbs_up", "user": "owner"}),
 113→    }).map_err(|e| anyhow::anyhow!("Failed to insert: {:?}", e))?;
 114→
 115→    // Wait for layer data to arrive on node
 116→    let node_data = wait_for_layer_data(
 117→        &s.node().butler,
 118→        &page_id,
 119→        "reactions",
 120→        Duration::from_secs(10),
 121→    ).await?;
 122→
 123→    assert!(!node_data.is_empty(), "Node should have received reactions layer data");
 124→
 125→    s.shutdown().await;
 126→    Ok(())
 127→}
