  1→//! 3-Step Sync Protocol
  2→//!
  3→//! Handles the SyncOffer → SyncAccept → SyncAck protocol for CRDT synchronization.
  4→//! Also includes asset sync triggering after layer sync completes.
  5→//!
  6→//! ## Bounded Resync Protocol
  7→//!
  8→//! When vectors diverge after SyncOffer/SyncAccept, we resync. But to prevent
  9→//! infinite loops, we track resync attempts:
 10→//!
 11→//! 1. `resync_attempts < MAX_RESYNC_ATTEMPTS`: Send another SyncOffer
 12→//! 2. `resync_attempts >= MAX_RESYNC_ATTEMPTS`: Send SyncReset (request full snapshot)
 13→//! 3. Node responds with SyncSnapshot (authoritative full state)
 14→//! 4. User replaces local layer entirely
 15→//!
 16→//! **Invariant**: Node is source of truth for divergence resolution.
 17→
 18→use tracing::{debug, error, info, trace, warn, instrument};
 19→use std::collections::BTreeSet;
 20→
 21→use crate::message::*;
 22→use transport::Connection;
 23→
 24→use super::super::guards::require_auth;
 25→use super::super::{PeerActor, PeerActorState, MAX_RESYNC_ATTEMPTS};
 26→
 27→impl<C: Connection> PeerActor<C> {
 28→
 29→    fn is_sync_meta_layer(page_id: &str, layer_name: &str) -> bool {
 30→        layer_name.starts_with("__sync_meta/")
 31→            || layer_name.starts_with(&format!("{}/__sync_meta/", page_id))
 32→    }
 33→
 34→    fn authority_schema_for_layer<'a>(
 35→        permit: &'a gurkha::Permit,
 36→        page_id: &str,
 37→        layer_name: &str,
 38→    ) -> Option<&'a gurkha::DynamicLayerSchema> {
 39→        let schemas = permit.dynamic_layer_schemas();
 40→        if schemas.is_empty() {
 41→            return None;
 42→        }
 43→
 44→        let bare_path = layer_name
 45→            .strip_prefix(&format!("{}/", page_id))
 46→            .unwrap_or(layer_name);
 47→        let path_parts: Vec<&str> = bare_path.split('/').collect();
 48→        if path_parts.len() < 3 || !path_parts[1].starts_with("did:") {
 49→            return None;
 50→        }
 51→
 52→        for (schema_key, schema) in schemas {
 53→            let pattern_parts: Vec<&str> = schema_key.split('/').collect();
 54→            if path_parts.len() != pattern_parts.len() + 1 {
 55→                continue;
 56→            }
 57→            if path_parts[0] != pattern_parts[0] {
 58→                continue;
 59→            }
 60→
 61→            let mut matched = true;
 62→            for (path_seg, pat_seg) in path_parts[2..].iter().zip(pattern_parts[1..].iter()) {
 63→                if *pat_seg != "{id}" && path_seg != pat_seg {
 64→                    matched = false;
 65→                    break;
 66→                }
 67→            }
 68→
 69→            if matched {
 70→                return Some(schema);
 71→            }
 72→        }
 73→
 74→        None
 75→    }
 76→
 77→    #[instrument(skip(self, authority_permit, scribe, state), fields(page_id = %page_id, layer = %layer_name))]
 78→    async fn fanout_sync_meta_from_authority(
 79→        &self,
 80→        page_id: &str,
 81→        layer_name: &str,
 82→        authority_permit: &gurkha::Permit,
 83→        scribe: &ractor::ActorRef<butler::ScribeMessage>,
 84→        state: &PeerActorState<C>,
 85→    ) {
 86→        let our_did = match state.butler.user_info().await {
 87→            Ok(info) => info.did,
 88→            Err(e) => {
 89→                warn!(error = %e, "Unable to resolve node DID for sync-meta fanout");
 90→                return;
 91→            }
 92→        };
 93→
 94→        let mut recipients = BTreeSet::new();
 95→        match authority_permit.authorized_peers() {
 96→            Ok(Some(explicit)) => {
 97→                for did in explicit {
 98→                    if did != our_did {
 99→                        recipients.insert(did);
100→                    }
101→                }
102→            }
103→            Ok(None) => {
104→                // Authority permit doesn't carry dynamic_layer_schemas — look up
105→                // the node's own page permit which has them.
106→                let our_page_permit = match state.butler.pages().get(page_id) {
107→                    Ok(Some(page)) => page.permit,
108→                    _ => None,
109→                };
110→                let parsed_page_permit = our_page_permit.as_deref().and_then(|t| gurkha::Permit::from_token(t).ok());
111→                let schema = parsed_page_permit.as_ref().and_then(|p| {
112→                    Self::authority_schema_for_layer(p, page_id, layer_name)
113→                });
114→                let Some(schema) = schema else {
115→                    warn!(page_id = %page_id, layer = %layer_name, "No matching dynamic schema in page permit for role fanout");
116→                    return;
117→                };
118→
119→                let all_users = match state.butler.store().list_authorized_users_for_page(page_id) {
120→                    Ok(users) => users,
121→                    Err(e) => {
122→                        warn!(error = %e, "Failed to list authorized users for role fanout");
123→                        return;
124→                    }
125→                };
126→
127→                for user_did in all_users {
128→                    if user_did == our_did {
129→                        continue;
130→                    }
131→
132→                    let permit_token = match state.butler.store().get_user_page_permit(page_id, &user_did) {
133→                        Ok(Some(p)) => p,
134→                        _ => continue,
135→                    };
136→
137→                    let parsed = match gurkha::Permit::from_token(&permit_token) {
138→                        Ok(p) => p,
139→                        Err(_) => continue,
140→                    };
141→
142→                    let role = parsed
143→                        .get_fact("role")
144→                        .and_then(|v| v.as_str())
145→                        .or_else(|| parsed.get_fact("relationship").and_then(|v| v.as_str()));
146→
147→                    if let Some(role) = role {
148→                        if schema.role_permissions.contains_key(role) {
149→                            recipients.insert(user_did);
150→                        }
151→                    }
152→                }
153→            }
154→            Err(e) => {
155→                warn!(error = %e, "Invalid authorized_peers in layer authority permit");
156→                return;
157→            }
158→        }
159→
160→        info!(page_id = %page_id, layer = %layer_name, count = recipients.len(), "Fanout sync-meta to recipients");
161→
162→        let bare_channel = layer_name
163→            .strip_prefix(&format!("{}/", page_id))
164→            .unwrap_or(layer_name);
165→
166→        for did in recipients {
167→            let sync_meta_layer = format!("__sync_meta/{}", did);
168→            let sync_meta_key = bare_channel.to_string();
169→            info!(page_id = %page_id, target = %did, sync_meta_layer = %sync_meta_layer, key = %sync_meta_key, "Writing sync-meta entry for recipient");
170→            if let Err(e) = scribe.cast(butler::ScribeMessage::MapInsert {
171→                layer_name: sync_meta_layer,
172→                path: String::new(),
173→                key: sync_meta_key.clone(),
174→                value: serde_json::json!({"synced": false, "version": 1}),
175→            }) {
176→                warn!(page_id = %page_id, layer = %layer_name, target = %did, error = %e, "Failed to write recipient sync-meta entry");
177→            }
178→
179→            // Authorize recipient on the channel layer so Scribe broadcasts reach them
180→            scribe.cast(butler::ScribeMessage::AuthorizeLayerSubscriber {
181→                layer_name: bare_channel.to_string(),
182→                subscriber_did: did.clone(),
183→            }).ok();
184→            info!(page_id = %page_id, target = %did, layer = %bare_channel, "Authorized recipient on channel layer for broadcast");
185→        }
186→    }
187→
188→    #[instrument(skip(self, state, scribe), fields(page_id = %page_id, sync_meta_layer = %sync_meta_layer))]
189→    async fn request_missing_layers_from_sync_meta(
190→        &self,
191→        page_id: &str,
192→        sync_meta_layer: &str,
193→        scribe: &ractor::ActorRef<butler::ScribeMessage>,
194→        state: &mut PeerActorState<C>,
195→    ) {
196→        let normalized_sync_meta_layer = sync_meta_layer
197→            .strip_prefix(&format!("{}/", page_id))
198→            .unwrap_or(sync_meta_layer)
199→            .to_string();
200→
201→        let (data_tx, data_rx) = tokio::sync::oneshot::channel();
202→        if let Err(e) = scribe.cast(butler::ScribeMessage::GetLayerData {
203→            layer_name: normalized_sync_meta_layer,
204→            reply: data_tx,
205→        }) {
206→            warn!(error = %e, "Failed to read sync-meta layer for request planning");
207→            return;
208→        }
209→
210→        let sync_meta_json = match data_rx.await {
211→            Ok(Ok(v)) => v,
212→            Ok(Err(e)) => {
213→                warn!(error = %e, "GetLayerData failed for sync-meta layer");
214→                return;
215→            }
216→            Err(_) => {
217→                warn!("GetLayerData reply channel closed for sync-meta layer");
218→                return;
219→            }
220→        };
221→
222→        let Some(entries) = sync_meta_json.as_object() else {
223→            warn!("sync-meta layer content is not a map object");
224→            return;
225→        };
226→
227→        for (layer_name, entry) in entries {
228→            let normalized_layer_name = layer_name
229→                .strip_prefix(&format!("{}/", page_id))
230→                .unwrap_or(layer_name)
231→                .to_string();
232→
233→            if normalized_layer_name.starts_with("__sync_meta/") {
234→                continue;
235→            }
236→
237→            let should_request = entry
238→                .get("synced")
239→                .and_then(serde_json::Value::as_bool)
240→                .map(|s| !s)
241→                .unwrap_or(true);
242→            if !should_request {
243→                continue;
244→            }
245→
246→            let (exists_tx, exists_rx) = tokio::sync::oneshot::channel();
247→            if let Err(e) = scribe.cast(butler::ScribeMessage::LayerExists {
248→                layer_name: normalized_layer_name.clone(),
249→                reply: exists_tx,
250→            }) {
251→                warn!(layer = %normalized_layer_name, error = %e, "Failed to check layer existence");
252→                continue;
253→            }
254→
255→            let exists = match exists_rx.await {
256→                Ok(v) => v,
257→                Err(_) => {
258→                    warn!(layer = %normalized_layer_name, "LayerExists reply channel closed");
259→                    continue;
260→                }
261→            };
262→
263→            if exists {
264→                continue;
265→            }
266→
267→            info!(page_id = %page_id, layer = %normalized_layer_name, "Requesting missing layer via SyncReset after sync-meta discovery");
268→            let msg = Message::SyncReset(SyncResetMsg {
269→                page_id: page_id.to_string(),
270→                layer_name: normalized_layer_name,
271→            });
272→            self.send_message(&msg, state).await;
273→        }
274→    }
275→
276→    /// Handle incoming SyncOffer from peer (Step 1)
277→    ///
278→    /// **Context**: Peer has a layer update with their state vector
279→    /// **Peer sends**: SyncOffer with page_id, layer_name, encrypted data, state_vector
280→    /// **We decrypt**: ECDH with ephemeral_public + our encryption key
281→    /// **We apply**: Via Scribe.ApplyUpdateWithResult (handles merge)
282→    /// **We respond**: SyncAccept with our state vector after applying (only if successful)
283→    #[instrument(skip(self, myself, state, data, their_state_vector, ephemeral_public), fields(page_id = %page_id, layer_name = %layer_name))]
284→    pub(in crate::peer_actor) async fn on_sync_offer(
285→        &self,
286→        myself: ractor::ActorRef<super::super::PeerMessage>,
287→        page_id: &str,
288→        layer_name: &str,
289→        data: &[u8],
290→        their_state_vector: &[u8],
291→        ephemeral_public: &[u8; 32],
292→        authority_permit: Option<&str>,
293→        state: &mut PeerActorState<C>,
294→    ) {
295→        let (peer_did, _) = match require_auth(&state.state) {
296→            Ok(info) => (info.0.to_string(), info.1.to_string()),
297→            Err(_) => {
298→                warn!("SyncOffer from unauthenticated peer: {}", self.node_id);
299→                return;
300→            }
301→        };
302→
303→        let peer_device_id = self.node_id.to_string();
304→
305→        debug!(
306→            "SyncOffer: page={} layer={} ({} bytes, vector {} bytes) from {}",
307→            page_id, layer_name, data.len(), their_state_vector.len(), peer_did
308→        );
309→
310→        // Open page early so bundled authority fanout and apply share one Scribe handle.
311→        let scribe = match state.butler.open_page(page_id).await {
312→            Ok(s) => s,
313→            Err(e) => {
314→                error!("Failed to open page {}: {}", page_id, e);
315→                return;
316→            }
317→        };
318→
319→        if let Some(permit) = authority_permit {
320→            match gurkha::Permit::from_token(permit) {
321→                Ok(parsed) => {
322→                    if parsed.token_type() == Some("layer_authority") {
323→                        let audience = parsed.parsed().audience().to_string();
324→                        let version = parsed
325→                            .get_fact("version")
326→                            .and_then(|v| v.as_u64())
327→                            .unwrap_or(0);
328→                        let full_layer_name = if layer_name.starts_with(&format!("{}/", page_id)) {
329→                            layer_name.to_string()
330→                        } else {
331→                            format!("{}/{}", page_id, layer_name)
332→                        };
333→                        if let Err(e) = state.butler.permits().store_layer_authority_permit(
334→                            page_id,
335→                            &full_layer_name,
336→                            &audience,
337→                            version,
338→                            permit,
339→                        ) {
340→                            warn!(
341→                                page_id = %page_id,
342→                                layer = %full_layer_name,
343→                                audience = %audience,
344→                                error = %e,
345→                                "Failed to store bundled layer authority permit"
346→                            );
347→                        }
348→
349→                        if state.mode == crate::CourierMode::Node {
350→                            self
351→                                .fanout_sync_meta_from_authority(
352→                                    page_id,
353→                                    &full_layer_name,
354→                                    &parsed,
355→                                    &scribe,
356→                                    state,
357→                                )
358→                                .await;
359→                        }
360→                    }
361→                }
362→                Err(e) => {
363→                    warn!(page_id = %page_id, layer = %layer_name, error = %e, "Invalid bundled authority permit in SyncOffer");
364→                }
365→            }
366→        }
367→
368→        // Decrypt transit-encrypted update using ECDH
369→        let our_secret = match state.butler.encryption_key().await {
370→            Ok(key) => key,
371→            Err(e) => {
372→                error!("Failed to get encryption key for SyncOffer decryption: {}", e);
373→                return;
374→            }
375→        };
376→        let decrypted_data = match herald::decrypt_from_transfer(&our_secret, ephemeral_public, data) {
377→            Ok(data) => data,
378→            Err(e) => {
379→                error!("Failed to decrypt SyncOffer from {}: {}", peer_did, e);
380→                return;
381→            }
382→        };
383→
384→        // Auto-subscribe peer if not already subscribed (both Node and User modes)
385→        // For Node mode: Ensures can_write() can check viewer's write permissions
386→        // For User mode: Ensures node gets subscribed to viewer's scribe for bidirectional sync
387→        if !state.page_subscriptions.contains_key(page_id) {
388→            info!("Auto-subscribing peer {} to page {} from SyncOffer", peer_did, page_id);
389→            self.subscribe_to_page(myself.clone(), page_id, "", state).await;
390→        }
391→
392→        // Apply the update with result feedback
393→        let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
394→        if let Err(e) = scribe.cast(butler::ScribeMessage::ApplyUpdateWithResult {
395→            layer_name: layer_name.to_string(),
396→            update: decrypted_data,
397→            from_peer: Some((peer_did.clone(), peer_device_id.clone())),
398→            permit: None,
399→            reply: reply_tx,
400→        }) {
401→            error!("Failed to send ApplyUpdateWithResult to Scribe: {}", e);
402→            return;
403→        }
404→
405→        // Wait for apply result - only send SyncAccept if successful
406→        match reply_rx.await {
407→            Ok(Ok(())) => {
408→                debug!("ApplyUpdate succeeded for page={} layer={}", page_id, layer_name);
409→
410→                if Self::is_sync_meta_layer(page_id, layer_name) {
411→                    self
412→                        .request_missing_layers_from_sync_meta(page_id, layer_name, &scribe, state)
413→                        .await;
414→                }
415→            }
416→            Ok(Err(e)) => {
417→                warn!("ApplyUpdate rejected for page={} layer={}: {}", page_id, layer_name, e);
418→                // DO NOT send SyncAccept - this stops the infinite retry loop
419→                return;
420→            }
421→            Err(_) => {
422→                error!("ApplyUpdate reply channel closed for page={} layer={}", page_id, layer_name);
423→                return;
424→            }
425→        }
426→
427→        // Get our state vector after applying
428→        let (tx, rx) = tokio::sync::oneshot::channel();
429→        if let Err(e) = scribe.cast(butler::ScribeMessage::GetStateVector {
430→            layer_name: layer_name.to_string(),
431→            reply: tx.into(),
432→        }) {
433→            error!("Failed to request state vector from Scribe: {}", e);
434→            return;
435→        }
436→
437→        let our_state_vector = match rx.await {
438→            Ok(Ok(vector)) => vector,
439→            Ok(Err(e)) => {
440→                error!("Scribe returned error getting state vector: {}", e);
441→                return;
442→            }
443→            Err(_) => {
444→                error!("Scribe dropped state vector reply channel");
445→                return;
446→            }
447→        };
448→
449→        // Send SyncAccept with our state vector
450→        let msg = Message::SyncAccept(SyncAcceptMsg {
451→            page_id: page_id.to_string(),
452→            layer_name: layer_name.to_string(),
453→            state_vector: our_state_vector.clone(),
454→        });
455→
456→        self.send_message(&msg, state).await;
457→        debug!(
458→            "Sent SyncAccept for page={} layer={} to {} (our vector {} bytes)",
459→            page_id, layer_name, peer_did, our_state_vector.len()
460→        );
461→    }
462→
463→    /// Handle incoming SyncAccept from peer (Step 2)
464→    ///
465→    /// **Context**: Peer applied our update and reports their state vector
466→    /// **Peer sends**: SyncAccept with their state vector after applying
467→    /// **We compare**: Their vector with our current vector
468→    /// **If match**: Send SyncAck (sync complete)
469→    /// **If diverged**: Send new SyncOffer with full diff from their vector (resync)
470→    #[instrument(skip(self, state, their_state_vector), fields(page_id = %page_id, layer_name = %layer_name))]
471→    pub(in crate::peer_actor) async fn on_sync_accept(
472→        &self,
473→        page_id: &str,
474→        layer_name: &str,
475→        their_state_vector: &[u8],
476→        state: &mut PeerActorState<C>,
477→    ) {
478→        let (peer_did, _) = match require_auth(&state.state) {
479→            Ok(info) => (info.0.to_string(), info.1.to_string()),
480→            Err(_) => {
481→                warn!("SyncAccept from unauthenticated peer: {}", self.node_id);
482→                return;
483→            }
484→        };
485→
486→        debug!(
487→            "SyncAccept: page={} layer={} from {} (their vector {} bytes)",
488→            page_id, layer_name, peer_did, their_state_vector.len()
489→        );
490→
491→        // Get pending sync context (may not exist for fire-and-forget broadcasts)
492→        let key = (page_id.to_string(), layer_name.to_string());
493→        let pending = state.pending_sync_offers.remove(&key);
494→
495→        // Get our current state vector from Scribe
496→        let scribe = match state.butler.open_page(page_id).await {
497→            Ok(s) => s,
498→            Err(e) => {
499→                error!("Failed to open page {}: {}", page_id, e);
500→                return;
501→            }
502→        };
503→
504→        let (tx, rx) = tokio::sync::oneshot::channel();
505→        if let Err(e) = scribe.cast(butler::ScribeMessage::GetStateVector {
506→            layer_name: layer_name.to_string(),
507→            reply: tx.into(),
508→        }) {
509→            error!("Failed to request state vector from Scribe: {}", e);
510→            return;
511→        }
512→
513→        let our_current_vector = match rx.await {
514→            Ok(Ok(vector)) => vector,
515→            Ok(Err(e)) => {
516→                error!("Scribe returned error getting state vector: {}", e);
517→                return;
518→            }
519→            Err(_) => {
520→                error!("Scribe dropped state vector reply channel");
521→                return;
522→            }
523→        };
524→
525→        // Handle based on whether we have a pending offer
526→        match pending {
527→            None => {
528→                // Fire-and-forget broadcast: No pending offer tracked.
529→                // Just update peer vector cache and send SyncAck. Trust CRDT to converge.
530→                debug!(
531→                    "SyncAccept: no pending offer (fire-and-forget) for page={} layer={} - sending SyncAck",
532→                    page_id, layer_name
533→                );
534→
535→                let msg = Message::SyncAck(SyncAckMsg {
536→                    page_id: page_id.to_string(),
537→                    layer_name: layer_name.to_string(),
538→                    state_vector: our_current_vector,
539→                });
540→                self.send_message(&msg, state).await;
541→
542→                // Update Scribe's in-memory vector cache (persistence via periodic flush)
543→                let peer_device_id = self.node_id.to_string();
544→                if let Some(subscription) = state.page_subscriptions.get(page_id) {
545→                    let _ = subscription.scribe.cast(butler::ScribeMessage::UpdatePeerVector {
546→                        user_did: peer_did,
547→                        device_id: peer_device_id,
548→                        layer_name: layer_name.to_string(),
549→                        state_vector: their_state_vector.to_vec(),
550→                    });
551→                }
552→            }
553→            Some(offer) => {
554→                // Tracked sync (initial sync / reconciliation): Compare vectors
555→                trace!(
556→                    "SyncAccept comparison: their_vector={} bytes, offered_vector={} bytes, current_vector={} bytes",
557→                    their_state_vector.len(),
558→                    offer.our_state_vector.len(),
559→                    our_current_vector.len()
560→                );
561→
562→                if their_state_vector == offer.our_state_vector.as_slice() {
563→                    // In sync! Send SyncAck
564→                    trace!(
565→                        "SyncAccept: vectors match for page={} layer={} - sending SyncAck",
566→                        page_id, layer_name
567→                    );
568→
569→                    let msg = Message::SyncAck(SyncAckMsg {
570→                        page_id: page_id.to_string(),
571→                        layer_name: layer_name.to_string(),
572→                        state_vector: our_current_vector,
573→                    });
574→                    self.send_message(&msg, state).await;
575→
576→                    // Update Scribe's in-memory vector cache (persistence via periodic flush)
577→                    let peer_device_id = self.node_id.to_string();
578→                    if let Some(subscription) = state.page_subscriptions.get(page_id) {
579→                        let _ = subscription.scribe.cast(butler::ScribeMessage::UpdatePeerVector {
580→                            user_did: peer_did,
581→                            device_id: peer_device_id,
582→                            layer_name: layer_name.to_string(),
583→                            state_vector: their_state_vector.to_vec(),
584→                        });
585→                    }
586→                } else {
587→                    // Diverged! Check if we should resync or fall back to SyncReset
588→                    let new_attempts = offer.resync_attempts + 1;
589→
590→                    if new_attempts > MAX_RESYNC_ATTEMPTS {
591→                        // Max resyncs exceeded - fall back to SyncReset (request full snapshot)
592→                        warn!(
593→                            "SyncAccept: max resyncs ({}) exceeded for page={} layer={} - sending SyncReset",
594→                            MAX_RESYNC_ATTEMPTS, page_id, layer_name
595→                        );
596→
597→                        let msg = Message::SyncReset(SyncResetMsg {
598→                            page_id: page_id.to_string(),
599→                            layer_name: layer_name.to_string(),
600→                        });
601→                        self.send_message(&msg, state).await;
602→                        return;
603→                    }
604→
605→                    // Still have retries - send resync SyncOffer with full diff from their vector
606→                    info!(
607→                        "SyncAccept: vectors DIVERGED for page={} layer={} - sending resync SyncOffer (attempt {}/{})",
608→                        page_id, layer_name, new_attempts, MAX_RESYNC_ATTEMPTS
609→                    );
610→
611→                    // Get diff from their state vector
612→                    let (tx, rx) = tokio::sync::oneshot::channel();
613→                    if let Err(e) = scribe.cast(butler::ScribeMessage::GetUpdatesSince {
614→                        layer_name: layer_name.to_string(),
615→                        state_vector: their_state_vector.to_vec(),
616→                        reply: tx,
617→                    }) {
618→                        error!("Failed to request updates from Scribe: {}", e);
619→                        return;
620→                    }
621→
622→                    let diff = match rx.await {
623→                        Ok(Ok(d)) => d,
624→                        Ok(Err(e)) => {
625→                            error!("Scribe returned error getting updates: {}", e);
626→                            return;
627→                        }
628→                        Err(_) => {
629→                            error!("Scribe dropped updates reply channel");
630→                            return;
631→                        }
632→                    };
633→
634→                    // Encrypt and send new SyncOffer
635→                    let peer_encryption_key = match state.peer_encryption_key {
636→                        Some(key) => key,
637→                        None => {
638→                            warn!("Cannot send resync SyncOffer: peer encryption key not set");
639→                            return;
640→                        }
641→                    };
642→
643→                    let (ephemeral_public, encrypted_data) = match herald::encrypt_for_transfer(
644→                        &peer_encryption_key,
645→                        &diff,
646→                    ) {
647→                        Ok(result) => result,
648→                        Err(e) => {
649→                            error!("Failed to encrypt resync data: {}", e);
650→                            return;
651→                        }
652→                    };
653→
654→                    // Track this new pending sync with incremented attempt counter
655→                    state.pending_sync_offers.insert(
656→                        key,
657→                        super::super::PendingSyncOffer {
658→                            our_state_vector: our_current_vector.clone(),
659→                            permit: String::new(),
660→                            resync_attempts: new_attempts,
661→                        },
662→                    );
663→
664→                    let layer_name_owned = layer_name.to_string();
665→                    let msg = Message::SyncOffer(SyncOfferMsg {
666→                        page_id: page_id.to_string(),
667→                        layer_type: LayerType::from_layer_name(&layer_name_owned),
668→                        layer_name: layer_name_owned,
669→                        data: encrypted_data,
670→                        state_vector: our_current_vector,
671→                        ephemeral_public,
672→                        authority_permit: None,
673→                    });
674→                    self.send_message(&msg, state).await;
675→                }
676→            }
677→        }
678→    }
679→
680→    /// Handle incoming SyncAck from peer (Step 3)
681→    ///
682→    /// **Context**: Peer confirms sync complete after comparing vectors
683→    /// **Peer sends**: SyncAck with their final state vector
684→    /// **We do**: Update cached peer vector, log sync complete
685→    #[instrument(skip(self, state, their_state_vector), fields(page_id = %page_id, layer_name = %layer_name))]
686→    pub(in crate::peer_actor) async fn on_sync_ack(
687→        &self,
688→        page_id: &str,
689→        layer_name: &str,
690→        their_state_vector: &[u8],
691→        state: &mut PeerActorState<C>,
692→    ) {
693→        let (peer_did, _) = match require_auth(&state.state) {
694→            Ok(info) => (info.0.to_string(), info.1.to_string()),
695→            Err(_) => {
696→                warn!("SyncAck from unauthenticated peer: {}", self.node_id);
697→                return;
698→            }
699→        };
700→
701→        debug!(
702→            "SyncAck: page={} layer={} from {} - sync complete",
703→            page_id, layer_name, peer_did
704→        );
705→
706→        // Update Scribe's in-memory vector cache (persistence via periodic flush)
707→        let peer_device_id = self.node_id.to_string();
708→        if let Some(subscription) = state.page_subscriptions.get(page_id) {
709→            let _ = subscription.scribe.cast(butler::ScribeMessage::UpdatePeerVector {
710→                user_did: peer_did.clone(),
711→                device_id: peer_device_id.clone(),
712→                layer_name: layer_name.to_string(),
713→                state_vector: their_state_vector.to_vec(),
714→            });
715→
716→            if !Self::is_sync_meta_layer(page_id, layer_name) {
717→                if let Ok(user_info) = state.butler.user_info().await {
718→                    let sync_meta_layer = format!("__sync_meta/{}", user_info.did);
719→                    let sync_meta_key = layer_name
720→                        .strip_prefix(&format!("{}/", page_id))
721→                        .unwrap_or(layer_name)
722→                        .to_string();
723→                    let _ = subscription.scribe.cast(butler::ScribeMessage::MapInsert {
724→                        layer_name: sync_meta_layer,
725→                        path: String::new(),
726→                        key: sync_meta_key,
727→                        value: serde_json::json!({"synced": true, "version": 1}),
728→                    });
729→                }
730→            }
731→        }
732→
733→        // Clean up any pending sync for this page/layer (shouldn't exist but be safe)
734→        let key = (page_id.to_string(), layer_name.to_string());
735→        state.pending_sync_offers.remove(&key);
736→
737→        // Check if this is an assets layer sync - trigger asset fetch for missing blobs
738→        if layer_name == "assets" || layer_name.ends_with("/assets") {
739→            self.trigger_asset_sync_after_layer_sync(page_id, layer_name, state).await;
740→        }
741→    }
742→
743→    /// Handle incoming SyncReset from peer (fallback after max resyncs)
744→    ///
745→    /// **Context**: Peer exceeded MAX_RESYNC_ATTEMPTS OR explicitly needs layer snapshot.
746→    /// **Both modes**: Respond with SyncSnapshot when layer exists locally.
747→    #[instrument(skip(self, state), fields(page_id = %page_id, layer_name = %layer_name))]
748→    pub(in crate::peer_actor) async fn on_sync_reset(
749→        &self,
750→        page_id: &str,
751→        layer_name: &str,
752→        state: &mut PeerActorState<C>,
753→    ) {
754→        let peer_did = match require_auth(&state.state) {
755→            Ok((did, _)) => did.to_string(),
756→            Err(_) => {
757→                warn!("SyncReset from unauthenticated peer: {}", self.node_id);
758→                return;
759→            }
760→        };
761→
762→        info!(
763→            "SyncReset: page={} layer={} from {} - sending full snapshot",
764→            page_id, layer_name, peer_did
765→        );
766→
767→        // Get Scribe and export full snapshot
768→        let scribe = match state.butler.open_page(page_id).await {
769→            Ok(s) => s,
770→            Err(e) => {
771→                error!("Failed to open page {} for SyncReset: {}", page_id, e);
772→                return;
773→            }
774→        };
775→
776→        // Get full snapshot
777→        let (snapshot_tx, snapshot_rx) = tokio::sync::oneshot::channel();
778→        if let Err(e) = scribe.cast(butler::ScribeMessage::GetSnapshot {
779→            layer_name: layer_name.to_string(),
780→            reply: snapshot_tx,
781→        }) {
782→            error!("Failed to request snapshot from Scribe: {}", e);
783→            return;
784→        }
785→
786→        let snapshot = match snapshot_rx.await {
787→            Ok(Some(data)) => data,
788→            Ok(None) => {
789→                warn!("Layer {} not found in Scribe for SyncReset", layer_name);
790→                return;
791→            }
792→            Err(_) => {
793→                error!("Scribe dropped snapshot reply channel");
794→                return;
795→            }
796→        };
797→
798→        // Get state vector
799→        let (vector_tx, vector_rx) = tokio::sync::oneshot::channel();
800→        if let Err(e) = scribe.cast(butler::ScribeMessage::GetStateVector {
801→            layer_name: layer_name.to_string(),
802→            reply: vector_tx.into(),
803→        }) {
804→            error!("Failed to request state vector from Scribe: {}", e);
805→            return;
806→        }
807→
808→        let state_vector = match vector_rx.await {
809→            Ok(Ok(v)) => v,
810→            Ok(Err(e)) => {
811→                error!("Scribe returned error getting state vector: {}", e);
812→                return;
813→            }
814→            Err(_) => {
815→                error!("Scribe dropped state vector reply channel");
816→                return;
817→            }
818→        };
819→
820→        // Encrypt snapshot for transfer
821→        let peer_encryption_key = match state.peer_encryption_key {
822→            Some(key) => key,
823→            None => {
824→                warn!("Cannot send SyncSnapshot: peer encryption key not set");
825→                return;
826→            }
827→        };
828→
829→        let (ephemeral_public, encrypted_snapshot) = match herald::encrypt_for_transfer(
830→            &peer_encryption_key,
831→            &snapshot,
832→        ) {
833→            Ok(result) => result,
834→            Err(e) => {
835→                error!("Failed to encrypt snapshot: {}", e);
836→                return;
837→            }
838→        };
839→
840→        // Send SyncSnapshot
841→        let layer_name_owned = layer_name.to_string();
842→        let msg = Message::SyncSnapshot(SyncSnapshotMsg {
843→            page_id: page_id.to_string(),
844→            layer_type: LayerType::from_layer_name(&layer_name_owned),
845→            layer_name: layer_name_owned,
846→            snapshot: encrypted_snapshot,
847→            state_vector,
848→            ephemeral_public,
849→        });
850→        self.send_message(&msg, state).await;
851→
852→        info!(
853→            "Sent SyncSnapshot for page={} layer={} to {} ({} bytes)",
854→            page_id, layer_name, peer_did, snapshot.len()
855→        );
856→    }
857→
858→    /// Handle incoming SyncSnapshot from peer (response to SyncReset)
859→    ///
860→    /// **Context**: Peer responded to our SyncReset with a full snapshot.
861→    /// **Both modes**: Replace local layer with received state.
862→    #[instrument(skip(self, state, snapshot, their_state_vector, ephemeral_public), fields(page_id = %page_id, layer_name = %layer_name))]
863→    pub(in crate::peer_actor) async fn on_sync_snapshot(
864→        &self,
865→        page_id: &str,
866→        layer_name: &str,
867→        snapshot: &[u8],
868→        their_state_vector: &[u8],
869→        ephemeral_public: &[u8; 32],
870→        state: &mut PeerActorState<C>,
871→    ) {
872→        let peer_did = match require_auth(&state.state) {
873→            Ok((did, _)) => did.to_string(),
874→            Err(_) => {
875→                warn!("SyncSnapshot from unauthenticated peer: {}", self.node_id);
876→                return;
877→            }
878→        };
879→
880→        info!(
881→            "SyncSnapshot: page={} layer={} from {} ({} bytes) - replacing local state",
882→            page_id, layer_name, peer_did, snapshot.len()
883→        );
884→
885→        // Decrypt snapshot
886→        let our_secret = match state.butler.encryption_key().await {
887→            Ok(key) => key,
888→            Err(e) => {
889→                error!("Failed to get encryption key for SyncSnapshot decryption: {}", e);
890→                return;
891→            }
892→        };
893→
894→        let decrypted_snapshot = match herald::decrypt_from_transfer(&our_secret, ephemeral_public, snapshot) {
895→            Ok(data) => data,
896→            Err(e) => {
897→                error!("Failed to decrypt SyncSnapshot from {}: {}", peer_did, e);
898→                return;
899→            }
900→        };
901→
902→        // Get Scribe and replace layer
903→        let scribe = match state.butler.open_page(page_id).await {
904→            Ok(s) => s,
905→            Err(e) => {
906→                error!("Failed to open page {} for SyncSnapshot: {}", page_id, e);
907→                return;
908→            }
909→        };
910→
911→        // Replace layer with snapshot
912→        let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
913→        if let Err(e) = scribe.cast(butler::ScribeMessage::ReplaceLayer {
914→            layer_name: layer_name.to_string(),
915→            snapshot: decrypted_snapshot,
916→            reply: reply_tx,
917→        }) {
918→            error!("Failed to send ReplaceLayer to Scribe: {}", e);
919→            return;
920→        }
921→
922→        match reply_rx.await {
923→            Ok(Ok(())) => {
924→                info!(
925→                    "SyncSnapshot applied: page={} layer={} - sync recovery complete",
926→                    page_id, layer_name
927→                );
928→
929→                if Self::is_sync_meta_layer(page_id, layer_name) {
930→                    self
931→                        .request_missing_layers_from_sync_meta(page_id, layer_name, &scribe, state)
932→                        .await;
933→                }
934→            }
935→            Ok(Err(e)) => {
936→                error!("ReplaceLayer failed for page={} layer={}: {}", page_id, layer_name, e);
937→                return;
938→            }
939→            Err(_) => {
940→                error!("Scribe dropped ReplaceLayer reply channel");
941→                return;
942→            }
943→        }
944→
945→        // Update Scribe's in-memory vector cache (persistence via periodic flush)
946→        let peer_device_id = self.node_id.to_string();
947→        if let Some(subscription) = state.page_subscriptions.get(page_id) {
948→            let _ = subscription.scribe.cast(butler::ScribeMessage::UpdatePeerVector {
949→                user_did: peer_did.clone(),
950→                device_id: peer_device_id,
951→                layer_name: layer_name.to_string(),
952→                state_vector: their_state_vector.to_vec(),
953→            });
954→
955→            if !Self::is_sync_meta_layer(page_id, layer_name) {
956→                if let Ok(user_info) = state.butler.user_info().await {
957→                    let sync_meta_layer = format!("__sync_meta/{}", user_info.did);
958→                    let sync_meta_key = layer_name
959→                        .strip_prefix(&format!("{}/", page_id))
960→                        .unwrap_or(layer_name)
961→                        .to_string();
962→                    let _ = subscription.scribe.cast(butler::ScribeMessage::MapInsert {
963→                        layer_name: sync_meta_layer,
964→                        path: String::new(),
965→                        key: sync_meta_key,
966→                        value: serde_json::json!({"synced": true, "version": 1}),
967→                    });
968→                }
969→            }
970→        }
971→
972→        // Clean up any pending sync
973→        let key = (page_id.to_string(), layer_name.to_string());
974→        state.pending_sync_offers.remove(&key);
975→    }
976→}
