379→                            // Set up Loro observer so future changes emit page_update events
380→                            loro_observer::setup_layer_observer(state, &layer_name);
381→
382→                            // Notify UI about the discovered layer
383→                            sync::broadcast::notify_layer_discovered(state, &layer_name);
384→                        }
