  1→//! Layer Unit — Per-layer compute unit
  2→//!
  3→//! Consolidates all per-layer state (LoroDoc, dirty flag, local-only flag,
  4→//! observer subscription) into a single struct. Makes Scribe a thin router
  5→//! over LayerUnit instances.
  6→//!
  7→//! Also contains dynamic layer management (schema validation, permit preparation).
  8→
  9→mod dynamic;
 10→
 11→pub use dynamic::{
 12→    handle_create_dynamic_layer, prepare_layer_permits, find_matching_dynamic_schema,
 13→    handle_add_layer_access, handle_remove_layer_access,
 14→};
 15→
 16→use std::collections::HashSet;
 17→use std::sync::{Arc, RwLock};
 18→
 19→use domains::Layer;
 20→
 21→/// Per-layer compute unit — owns all state for a single layer
 22→pub struct LayerUnit {
 23→    /// The CRDT document
 24→    layer: Layer,
 25→    /// Needs flush to storage?
 26→    dirty: bool,
 27→    /// sync: false in permit — never broadcast
 28→    is_local_only: bool,
 29→    /// Created via dynamic_layer_schema (not static template)
 30→    pub is_dynamic: bool,
 31→    /// Loro observer subscription (dropped = unsubscribed)
 32→    loro_sub: Option<loro::Subscription>,
 33→    /// Which subscriber DIDs are authorized to receive updates for this layer.
 34→    /// Arc<RwLock> because the observer async task needs shared read access.
 35→    /// Populated at subscription time (page permit) and permit issuance (layer permits).
 36→    authorized_dids: Arc<RwLock<HashSet<String>>>,
 37→}
 38→
 39→impl LayerUnit {
 40→    /// Create a LayerUnit wrapping an existing layer
 41→    pub fn new(layer: Layer) -> Self {
 42→        Self {
 43→            layer,
 44→            dirty: false,
 45→            is_local_only: false,
 46→            is_dynamic: false,
 47→            loro_sub: None,
 48→            authorized_dids: Arc::new(RwLock::new(HashSet::new())),
 49→        }
 50→    }
 51→
 52→    /// Create a LayerUnit with an empty LoroDoc
 53→    pub fn new_empty() -> Self {
 54→        Self::new(Layer::new())
 55→    }
 56→
 57→    // Layer access
 58→
 59→    /// Get a reference to the inner Layer
 60→    pub fn layer(&self) -> &Layer {
 61→        &self.layer
 62→    }
 63→
 64→    /// Get a mutable reference to the inner Layer
 65→    pub fn layer_mut(&mut self) -> &mut Layer {
 66→        &mut self.layer
 67→    }
 68→
 69→    /// Replace the inner layer (e.g. snapshot restore)
 70→    pub fn replace_layer(&mut self, layer: Layer) {
 71→        self.layer = layer;
 72→    }
 73→
 74→    // Dirty tracking
 75→
 76→    /// Mark this layer as needing persistence
 77→    pub fn mark_dirty(&mut self) {
 78→        self.dirty = true;
 79→    }
 80→
 81→    /// Check if this layer needs persistence
 82→    pub fn is_dirty(&self) -> bool {
 83→        self.dirty
 84→    }
 85→
 86→    /// Clear the dirty flag without exporting
 87→    pub fn clear_dirty(&mut self) {
 88→        self.dirty = false;
 89→    }
 90→
 91→    /// Export snapshot if dirty, clear flag. Returns None if clean.
 92→    pub fn take_dirty_snapshot(&mut self) -> Option<Vec<u8>> {
 93→        if self.dirty {
 94→            self.dirty = false;
 95→            Some(self.layer.export_snapshot())
 96→        } else {
 97→            None
 98→        }
 99→    }
100→
101→    // Metadata
102→
103→    /// Check if this layer is local-only (sync: false)
104→    pub fn is_local_only(&self) -> bool {
105→        self.is_local_only
106→    }
107→
108→    /// Set the local-only flag
109→    pub fn set_local_only(&mut self, val: bool) {
110→        self.is_local_only = val;
111→    }
112→
113→    /// Check if this layer was created dynamically
114→    pub fn is_dynamic(&self) -> bool {
115→        self.is_dynamic
116→    }
117→
118→    // Observer lifecycle
119→
120→    /// Check if this layer has an active Loro observer
121→    pub fn has_observer(&self) -> bool {
122→        self.loro_sub.is_some()
123→    }
124→
125→    /// Set the Loro observer subscription
126→    pub fn set_observer(&mut self, sub: loro::Subscription) {
127→        self.loro_sub = Some(sub);
128→    }
129→
130→    /// Drop the observer (unsubscribes from Loro)
131→    pub fn clear_observer(&mut self) {
132→        self.loro_sub = None;
133→    }
134→
135→    // Authorization
136→
137→    /// Get shared reference to authorized_dids (for observer to clone the Arc)
138→    pub fn authorized_dids(&self) -> &Arc<RwLock<HashSet<String>>> {
139→        &self.authorized_dids
140→    }
141→
142→    /// Authorize a DID to receive updates for this layer
143→    pub fn authorize_did(&self, did: &str) {
144→        if let Ok(mut set) = self.authorized_dids.write() {
145→            set.insert(did.to_string());
146→        }
147→    }
148→
149→    /// Revoke a DID's authorization for this layer
150→    pub fn revoke_did(&self, did: &str) {
151→        if let Ok(mut set) = self.authorized_dids.write() {
152→            set.remove(did);
153→        }
154→    }
155→
156→    /// Check if a DID is authorized for this layer
157→    pub fn is_authorized(&self, did: &str) -> bool {
158→        self.authorized_dids.read()
159→            .map(|set| set.contains(did))
160→            .unwrap_or(false)
161→    }
162→}
