// runGitGC runs git gc to pack objects (simulates a realistic repo state).
func runGitGC(t *testing.T, dir string) {
	t.Helper()

	cmd := exec.Command("git", "gc", "--aggressive", "--prune=now")
	cmd.Dir = dir
	out, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("git gc: %v\n%s", err, out)
	}
}

arguments.new_string:
// timeGitGC runs git gc to pack objects and returns the duration.
func timeGitGC(t *testing.T, dir string) time.Duration {
	t.Helper()

	start := time.Now()
	cmd := exec.Command("git", "gc", "--aggressive", "--prune=now")
	cmd.Dir = dir
	out, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("git gc: %v\n%s", err, out)
	}
	return time.Since(start)
}

// formatBytes returns a human-readable size string.
func formatBytes(b int64) string {
	switch {
	case b >= 1024*1024:
		return fmt.Sprintf("%.1f MB", float64(b)/(1024*1024))
	case b >= 1024:
		return fmt.Sprintf("%d KB", b/1024)
	default:
		return fmt.Sprintf("%d B", b)
	}
}

